CustomField.formula:
OR(
 AND( INCLUDES( Asset_Class__c , "FI") ,
      INCLUDES( $User.Asset_Class__c , "FI")
     ),

 AND( INCLUDES( Asset_Class__c , "FX") ,
      INCLUDES( $User.Asset_Class__c , "FX")
     ),

 AND( INCLUDES( Asset_Class__c , "EQ") ,
      INCLUDES( $User.Asset_Class__c , "EQ")
     )
   )
